package cn.richie696.component.secret.provider.pkcs11;
import cn.richie696.component.secret.api.SecretCapability; import cn.richie696.component.secret.bootstrap.BootstrapSecretProperties; import cn.richie696.component.secret.bootstrap.spi.*; import java.util.Set;
@cn.richie696.component.secret.bootstrap.spi.SecretProviderType("pkcs11")
public final class Pkcs11SecretBootstrapProviderFactory implements SecretBootstrapProviderFactory { private static final Set<SecretCapability> CAPABILITIES=Set.of(SecretCapability.KEY_WRAP,SecretCapability.KEY_UNWRAP,SecretCapability.SIGN,SecretCapability.VERIFY); @Override public String providerType(){return "pkcs11";} @Override public Set<SecretCapability> capabilities(){return CAPABILITIES;} @Override public SecretBootstrapClient create(BootstrapSecretProperties p,SecretBootstrapContext c){return Pkcs11SecretClient.create(c.environment(),p,c);} }
